begin;
alter table private.staff_permissions
 add column can_manage_vaccine_catalog boolean not null default false,
 add column can_review_vaccine_catalog boolean not null default false;

create table private.vaccine_sources (
 id uuid primary key default gen_random_uuid(),
 sha256 text not null unique check(sha256 ~ '^[a-f0-9]{64}$'),
 document jsonb not null check(jsonb_typeof(document)='object'),
 imported_at timestamptz not null default now()
);
alter table private.vaccine_sources enable row level security;
create trigger vaccine_sources_immutable before update or delete on private.vaccine_sources for each row execute function private.prevent_mutation();

create table public.vaccine_versions (
 id uuid primary key default gen_random_uuid(),source_id uuid not null references private.vaccine_sources(id),
 parent_id uuid references public.vaccine_versions(id), label text not null check(length(trim(label)) between 3 and 120),
 status text not null default 'draft' check(status in ('draft','approved','retired')),
 revision integer not null default 1 check(revision>0),
 created_by uuid references public.professional_profiles(user_id),created_at timestamptz not null default now(),
 reviewed_by uuid references public.professional_profiles(user_id),reviewed_at timestamptz,
 review_reference text,review_verified boolean not null default false,
 check((status='draft' and reviewed_by is null and reviewed_at is null and not review_verified)
  or (status in ('approved','retired') and reviewed_by is not null and reviewed_at is not null and review_verified and review_reference is not null and length(trim(review_reference)) between 10 and 1000)
  or (status='retired' and reviewed_by is null and not review_verified))
);
create index vaccine_versions_source_idx on public.vaccine_versions(source_id);
create index vaccine_versions_parent_idx on public.vaccine_versions(parent_id);
create index vaccine_versions_creator_idx on public.vaccine_versions(created_by);
create index vaccine_versions_reviewer_idx on public.vaccine_versions(reviewed_by);
create table public.vaccine_rules (
 version_id uuid not null references public.vaccine_versions(id),dose_code text not null,
 vaccine_code text not null,source_row jsonb not null,source_age jsonb not null,
 age jsonb not null,eligibility text not null check(eligibility in ('all','female')),
 automatic_scheduling boolean not null,
 primary key(version_id,dose_code)
);
create table public.vaccine_catalog_changes (
 id uuid primary key default gen_random_uuid(),version_id uuid not null references public.vaccine_versions(id),
 actor_id uuid not null references public.professional_profiles(user_id),action text not null check(action in ('clone','edit','approve','retire')),
 revision integer not null,reason text not null check(length(trim(reason)) between 10 and 1000),
 evidence_reference text not null check(length(trim(evidence_reference)) between 10 and 1000),
 snapshot jsonb not null,created_at timestamptz not null default now()
);
create index vaccine_catalog_changes_version_idx on public.vaccine_catalog_changes(version_id,created_at,id);
create index vaccine_catalog_changes_actor_idx on public.vaccine_catalog_changes(actor_id);
create trigger vaccine_catalog_changes_immutable before update or delete on public.vaccine_catalog_changes for each row execute function private.prevent_mutation();
create trigger vaccine_catalog_changes_audit after insert on public.vaccine_catalog_changes for each row execute function private.audit_change();
alter table public.vaccine_versions enable row level security;
alter table public.vaccine_rules enable row level security;
alter table public.vaccine_catalog_changes enable row level security;
revoke all on private.vaccine_sources,public.vaccine_versions,public.vaccine_rules,public.vaccine_catalog_changes from public,anon,authenticated;

create function private.vaccine_catalog_permissions() returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object(
  'manage',coalesce(private.has_live_session() and p.role='admin' and p.verification_status='approved' and s.can_manage_vaccine_catalog,false),
  'review',coalesce(private.has_clinical_capability('vaccination') and s.can_review_vaccine_catalog,false))
 from (select 1) x left join public.professional_profiles p on p.user_id=auth.uid()
 left join private.staff_permissions s on s.user_id=p.user_id;
$$;
create function private.assert_vaccine_catalog_reader() returns void
language plpgsql stable security definer set search_path='' as $$
declare rights jsonb:=private.vaccine_catalog_permissions();
begin
 if (rights->>'manage')::boolean or (rights->>'review')::boolean then return; end if;
 perform private.assert_doctor();
end;$$;

create function private.guard_vaccine_rule() returns trigger
language plpgsql set search_path='' as $$
declare v public.vaccine_versions; original jsonb; n integer;
begin
 if tg_op='DELETE' then raise exception 'Catalog rules cannot be deleted' using errcode='42501'; end if;
 select * into v from public.vaccine_versions where id=new.version_id for update;
 if v.status is distinct from 'draft' then raise exception 'Published catalog content is immutable' using errcode='42501'; end if;
 if tg_op='UPDATE' and (new.version_id<>old.version_id or new.dose_code<>old.dose_code or new.vaccine_code<>old.vaccine_code or new.source_row<>old.source_row or new.source_age<>old.source_age) then raise exception 'Source mapping is immutable' using errcode='42501'; end if;
 select r into original from private.vaccine_sources s cross join lateral jsonb_array_elements(s.document->'schedule_2025') r where s.id=v.source_id and r->>'dose_code'=new.dose_code;
 if original is null or new.source_row is distinct from original or new.source_age is distinct from original->'source_age' or new.vaccine_code is distinct from original->>'vaccine_code' then raise exception 'Original source mapping required' using errcode='22023'; end if;
 if jsonb_typeof(new.age) is distinct from 'object' or new.age->>'unit' is null or new.age->>'unit' not in ('first_4_weeks','weeks','months','years') or (new.age-'unit'-'value')<>'{}'::jsonb then raise exception 'Invalid routine age' using errcode='22023'; end if;
 if new.age->>'unit'='first_4_weeks' then
  if new.age ? 'value' then raise exception 'Birth window has no exact age' using errcode='22023'; end if;
 else
  if jsonb_typeof(new.age->'value') is distinct from 'number' or (new.age->>'value') !~ '^[1-9][0-9]{0,3}$' then raise exception 'Integer routine age required' using errcode='22023'; end if;
  n:=(new.age->>'value')::integer;
  if n>(case new.age->>'unit' when 'years' then 20 when 'months' then 240 else 1040 end) then raise exception 'Routine age outside bounds' using errcode='22023'; end if;
 end if;
 if (new.dose_code='HB1' and (new.automatic_scheduling or new.age is distinct from original->'age'))
  or (new.dose_code in ('BCG','VPO0') and new.age is distinct from '{"unit":"first_4_weeks"}'::jsonb)
  or (new.dose_code='HPV' and (new.age is distinct from '{"unit":"years","value":11}'::jsonb or new.eligibility<>'female'))
  or (new.dose_code<>'HPV' and new.eligibility<>'all')
  or (new.dose_code in ('Rota1','Rota2','Rota3') and new.age is distinct from original->'age') then raise exception 'Agreed HB1/birth-window/HPV/rotavirus constraint' using errcode='22023'; end if;
 return new;
end;$$;
create trigger vaccine_rule_guard before insert or update or delete on public.vaccine_rules for each row execute function private.guard_vaccine_rule();
create function private.guard_vaccine_version() returns trigger
language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'Catalog versions cannot be deleted' using errcode='42501'; end if;
 if new.id<>old.id or new.source_id<>old.source_id or new.parent_id is distinct from old.parent_id or new.created_by is distinct from old.created_by or new.created_at<>old.created_at or new.revision<>old.revision+1
  or old.status='retired' or (old.status='approved' and (new.status<>'retired' or new.label<>old.label or new.reviewed_by is distinct from old.reviewed_by or new.reviewed_at is distinct from old.reviewed_at or new.review_reference is distinct from old.review_reference or new.review_verified<>old.review_verified)) then raise exception 'Immutable version or invalid transition' using errcode='42501'; end if;
 return new;
end;$$;
create trigger vaccine_version_guard before update or delete on public.vaccine_versions for each row execute function private.guard_vaccine_version();

create function private.vaccine_version_snapshot(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select to_jsonb(v)||jsonb_build_object('source_sha256',s.sha256,'source_document',s.document,
 'rules',coalesce((select jsonb_agg(to_jsonb(r) order by r.dose_code) from public.vaccine_rules r where r.version_id=v.id),'[]'::jsonb))
 from public.vaccine_versions v join private.vaccine_sources s on s.id=v.source_id where v.id=p_id;
$$;
create function private.vaccine_catalog(p_version_id uuid default null,p_page integer default 1) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 perform private.assert_vaccine_catalog_reader();
 if p_page is null or p_page not between 1 and 10000 then raise exception 'Invalid catalog page' using errcode='22023'; end if;
 if p_version_id is null then
  return jsonb_build_object('permissions',private.vaccine_catalog_permissions(),'total',(select count(*) from public.vaccine_versions),'versions',coalesce((select jsonb_agg(to_jsonb(v) order by v.created_at desc,v.id) from (select * from public.vaccine_versions order by created_at desc,id limit 20 offset (p_page-1)*20) v),'[]'::jsonb));
 end if;
 if not exists(select 1 from public.vaccine_versions where id=p_version_id) then raise exception 'Unknown version' using errcode='22023'; end if;
 return jsonb_build_object('permissions',private.vaccine_catalog_permissions(),'version',private.vaccine_version_snapshot(p_version_id),
  'history_total',(select count(*) from public.vaccine_catalog_changes where version_id=p_version_id),'history',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at,c.id) from (select * from public.vaccine_catalog_changes where version_id=p_version_id order by created_at,id limit 20 offset (p_page-1)*20) c),'[]'::jsonb));
end;$$;

create function private.change_vaccine_catalog(p_operation_id uuid,p_action text,p_version_id uuid,p_expected_revision integer,p_input jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare rights jsonb:=private.vaccine_catalog_permissions(); v public.vaccine_versions; result uuid; receipt private.operation_receipts;
 payload jsonb:=jsonb_build_object('action',p_action,'version',p_version_id,'revision',p_expected_revision,'input',p_input);
 reason text:=trim(p_input->>'reason'); evidence text:=trim(p_input->>'evidence_reference');
begin
 if p_action is null or p_action not in ('clone','edit','approve','retire') then raise exception 'Unknown catalog action' using errcode='22023'; end if;
 if not coalesce((rights->>(case when p_action='approve' then 'review' else 'manage' end))::boolean,false) then raise exception 'Explicit catalog permission required' using errcode='42501'; end if;
 if p_operation_id is null or p_input is null or jsonb_typeof(p_input)<>'object' or reason is null or length(reason) not between 10 and 1000 or evidence is null or length(evidence) not between 10 and 1000 then raise exception 'Operation, reason and evidence required' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_operation_id::text,0));
 select * into receipt from private.operation_receipts where actor_id=auth.uid() and operation_id=p_operation_id;
 if found then
  if receipt.kind<>'vaccine_catalog' or receipt.payload is distinct from payload then raise exception 'Operation ID reused with different input' using errcode='22023'; end if;
  return receipt.result_id;
 end if;
 select * into v from public.vaccine_versions where id=p_version_id for update;
 if not found then raise exception 'Unknown catalog version' using errcode='22023'; end if;
 if p_expected_revision is distinct from v.revision then raise exception 'Stale catalog revision' using errcode='PT409'; end if;
 if p_action='clone' then
  if p_input->>'label' is null or length(trim(p_input->>'label')) not between 3 and 120 then raise exception 'Version label required' using errcode='22023'; end if;
  insert into public.vaccine_versions(source_id,parent_id,label,created_by) values(v.source_id,v.id,trim(p_input->>'label'),auth.uid()) returning id into result;
  insert into public.vaccine_rules select result,dose_code,vaccine_code,source_row,source_age,age,eligibility,automatic_scheduling from public.vaccine_rules where version_id=v.id;
 elsif p_action='edit' then
  if v.status<>'draft' then raise exception 'Draft version required' using errcode='42501'; end if;
  if p_input->>'dose_code' is null or p_input->'age' is null or p_input->>'eligibility' is null or jsonb_typeof(p_input->'automatic_scheduling') is distinct from 'boolean' then raise exception 'Complete rule required' using errcode='22023'; end if;
  update public.vaccine_rules set age=p_input->'age',eligibility=p_input->>'eligibility',automatic_scheduling=(p_input->>'automatic_scheduling')::boolean where version_id=v.id and dose_code=p_input->>'dose_code';
  if not found then raise exception 'Unknown source dose' using errcode='22023'; end if;
  update public.vaccine_versions set revision=revision+1 where id=v.id;
  result:=v.id;
 elsif p_action='approve' then
  if v.status<>'draft' then raise exception 'Draft version required' using errcode='42501'; end if;
  if v.created_by=auth.uid() or exists(select 1 from public.vaccine_catalog_changes where version_id=v.id and actor_id=auth.uid() and action in ('clone','edit')) then raise exception 'Independent clinical reviewer required' using errcode='42501'; end if;
  if p_input->'source_authenticated' is distinct from 'true'::jsonb or p_input->'clinical_reviewed' is distinct from 'true'::jsonb or p_input->'birth_window_reviewed' is distinct from 'true'::jsonb then raise exception 'Source, complete clinical review and birth-window interpretation required' using errcode='22023'; end if;
  if (select count(*) from public.vaccine_rules where version_id=v.id)<>25 then raise exception 'Complete 25-dose catalog required' using errcode='22023'; end if;
  update public.vaccine_versions set revision=revision+1,status='approved',reviewed_by=auth.uid(),reviewed_at=now(),review_reference=evidence,review_verified=true where id=v.id;
  result:=v.id;
 else
  if v.status='retired' then raise exception 'Version already retired' using errcode='PT409'; end if;
  update public.vaccine_versions set revision=revision+1,status='retired' where id=v.id;
  result:=v.id;
 end if;
 insert into public.vaccine_catalog_changes(version_id,actor_id,action,revision,reason,evidence_reference,snapshot)
 select result,auth.uid(),p_action,revision,reason,evidence,private.vaccine_version_snapshot(result) from public.vaccine_versions where id=result;
 insert into private.operation_receipts(actor_id,operation_id,kind,payload,result_id) values(auth.uid(),p_operation_id,'vaccine_catalog',payload,result);
 return result;
end;$$;

create function public.vaccine_catalog_permissions() returns jsonb language sql stable security invoker set search_path='' as $$select private.vaccine_catalog_permissions();$$;
create function public.vaccine_catalog(p_version_id uuid default null,p_page integer default 1) returns jsonb language sql stable security invoker set search_path='' as $$select private.vaccine_catalog(p_version_id,p_page);$$;
create function public.change_vaccine_catalog(p_operation_id uuid,p_action text,p_version_id uuid,p_expected_revision integer,p_input jsonb) returns uuid language sql security invoker set search_path='' as $$select private.change_vaccine_catalog(p_operation_id,p_action,p_version_id,p_expected_revision,p_input);$$;
revoke all on function private.vaccine_catalog_permissions(),private.assert_vaccine_catalog_reader(),private.guard_vaccine_rule(),private.guard_vaccine_version(),private.vaccine_version_snapshot(uuid),private.vaccine_catalog(uuid,integer),private.change_vaccine_catalog(uuid,text,uuid,integer,jsonb),public.vaccine_catalog_permissions(),public.vaccine_catalog(uuid,integer),public.change_vaccine_catalog(uuid,text,uuid,integer,jsonb) from public,anon,authenticated;
grant execute on function private.vaccine_catalog_permissions(),private.vaccine_catalog(uuid,integer),private.change_vaccine_catalog(uuid,text,uuid,integer,jsonb),public.vaccine_catalog_permissions(),public.vaccine_catalog(uuid,integer),public.change_vaccine_catalog(uuid,text,uuid,integer,jsonb) to authenticated;

